"""Native response schemas generated by Codex 0.162.1 (app-server generate-json-schema).

Each method owns its reply shape. Validation never translates a native decision,
fills in a grant, or supplies an omitted scope on the caller's behalf.
"""
from functools import lru_cache
from importlib.resources import files
import json

from .models import ConversationError


@lru_cache(maxsize=1)
def schemas():
    return json.loads(files("conversation_manager").joinpath("native_response_schemas.json").read_text())


def response_schema(method):
    return schemas().get(method, {"type": "object"})


def validate_response(record, value):
    from jsonschema import Draft7Validator

    if not Draft7Validator(response_schema(record["native_method"])).is_valid(value):
        raise ConversationError("validation", "Response does not satisfy the native method's response schema")
